%[text] ## Problem 2-B. Modeling flow over hydrophobic surfaces
%[text] \[From the undergrad fluid fundamentals material $\\rightarrow$ Ref: ME333\_SP26\_Final\_Exam.doc, and notebook pp. 119 - 122\]
%[text] ### Couette-Poiseuille flow with Navier slip at the lower wall
%% Problem 2, Part 1
% Couette-Poiseuille flow with Navier slip at the lower wall

clear; clc; close all;

%% Given / user-defined parameters

U    = 1.0;          % upper plate speed [m/s]
G    = 1000;         % positive pressure-gradient magnitude, dp/dx = -G [Pa/m]
mu   = 1.0e-3;       % dynamic viscosity [Pa*s]
h    = 0.01;         % plate spacing [m]
b    = 0.002;        % slip length at lower wall [m]

%% y-domain

N = 500;
y = linspace(0,h,N);

%% Velocity profile

u = -(G/(2*mu)).*y.^2 ...
    + ((U/(h + b) + (G*h^2)/((2*mu)*(h+b)))).*(y + b);

%% Plot velocity profile

fig = figure(Color="w"); %[output:5fee1c24]
try
    fig.Theme = "Light"; %[output:5fee1c24]
end

plot(u,y,'LineWidth',2); %[output:5fee1c24]
grid on; %[output:5fee1c24]
box on; %[output:5fee1c24]

xlabel('Velocity, u(y) [m/s]'); %[output:5fee1c24]
ylabel('Gap coordinate, y [m]'); %[output:5fee1c24]
title('Velocity Profile for Couette-Poiseuille Flow with Slip'); %[output:5fee1c24]

ylim([0 h]); %[output:5fee1c24]

%% Add wall labels

hold on; %[output:5fee1c24]
yline(0,'--','Lower wall, y = 0','LabelHorizontalAlignment','left'); %[output:5fee1c24]
yline(h,'--','Upper wall, y = h','LabelHorizontalAlignment','left'); %[output:5fee1c24]

%% Display useful values

u_lower = u(1);
u_upper = u(end);

fprintf('Lower-wall velocity u(0) = %.6f m/s\n',u_lower); %[output:17c8697c]
fprintf('Upper-wall velocity u(h) = %.6f m/s\n',u_upper); %[output:85cde2d7]
fprintf('Expected upper-wall velocity U = %.6f m/s\n',U); %[output:98ccc38a]
%%
%[text] ### Shear stress distribution for Couette-Poiseuille flow with slip
%% Problem 2, Part 3
% Shear stress distribution for Couette-Poiseuille flow with slip

%% Given / user-defined parameters

U    = 1.0;        % upper plate speed [m/s]
G    = 1000;       % pressure-gradient magnitude, dp/dx = -G [Pa/m]
mu   = 1.0e-3;     % dynamic viscosity [Pa*s]
h    = 0.01;       % plate spacing [m]
b = 0.002;      % slip length at lower wall [m]

%% y-domain

N = 500;
y = linspace(0,h,N);

%% Shear stress distribution

tau = -G.*y + (mu*U + (G*h^2)/2)/(h + b);

%% Wall shear stresses

tau_0 = tau(1);      % shear stress at lower wall, y = 0
tau_h = tau(end);    % shear stress at upper wall, y = h

%% Plot shear stress distribution

fig = figure(Color="w"); %[output:43faf11e]
try
    fig.Theme = "Light"; %[output:43faf11e]
end

plot(tau,y,'LineWidth',2); %[output:43faf11e]
grid on; %[output:43faf11e]
box on; %[output:43faf11e]

xlabel('Shear stress, \tau(y) [Pa]'); %[output:43faf11e]
ylabel('Gap coordinate, y [m]'); %[output:43faf11e]
title('Shear Stress Distribution'); %[output:43faf11e]

ylim([0 h]); %[output:43faf11e]

hold on; %[output:43faf11e]

% Mark lower and upper wall shear stresses
plot(tau_0,0,'o','MarkerSize',8,'LineWidth',2); %[output:43faf11e]
plot(tau_h,h,'o','MarkerSize',8,'LineWidth',2); %[output:43faf11e]

% Add wall labels
yline(0,'--','Lower wall, y = 0','LabelHorizontalAlignment','left'); %[output:43faf11e]
yline(h,'--','Upper wall, y = h','LabelHorizontalAlignment','left'); %[output:43faf11e]

% Add vertical zero-stress line
xline(0,'--','\tau = 0'); %[output:43faf11e]

legend('\tau(y)', '\tau_0', '\tau_h', 'Location','best'); %[output:43faf11e]

%% Print values to command window

fprintf('Lower-wall shear stress tau_0 = %.6f Pa\n', tau_0); %[output:0083e80d]
fprintf('Upper-wall shear stress tau_h = %.6f Pa\n', tau_h); %[output:5349a4bb]
fprintf('Slope d(tau)/dy = %.6f Pa/m\n', -G); %[output:5ed04d66]
